'use strict';
const $=id=>document.getElementById(id), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=(x,d=2)=>Number(x).toLocaleString('en-US',{minimumFractionDigits:d,maximumFractionDigits:d}), integer=x=>num(x,0), usd=x=>`${x<0?'−':''}$${num(Math.abs(x))}`, prob=x=>x===0?'Below floating-point resolution (not zero)':x<.0001?x.toExponential(3):Number(x.toPrecision(5)).toString();
const COLORS=['#0072b2','#c45b18','#178259'], DASH=['','7 4','2 3'];
let DATA;
function put(id,text){$(id).textContent=text;}
function table(id,rows,columns){if(!rows?.length)return;const keys=columns||Object.keys(rows[0]);$(id).innerHTML=`<div class="table-wrap" tabindex="0" aria-label="Scrollable results table"><table><thead><tr>${keys.map(k=>`<th scope="col">${esc(k)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${keys.map((k,i)=>{let v=r[k];if(typeof v==='number')v=/p-value|^p$/.test(k)?prob(v):/\bn\b|count|replications|Excluded|Remaining/i.test(k)?integer(v):/^(t|F)$/.test(k)?num(v,5):/df$/.test(k)&&Number.isInteger(v)?integer(v):num(v);if(typeof v==='boolean')v=v?'Yes':'No';return `<${i?'td':'th scope="row"'}>${esc(v??'—')}</${i?'td':'th'}>`}).join('')}</tr>`).join('')}</tbody></table></div>`;}

const plotJobs=[];
const config={responsive:true,displaylogo:false,scrollZoom:false,modeBarButtons:[['toImage'],['zoom2d','pan2d','zoomIn2d','zoomOut2d','autoScale2d','resetScale2d']],toImageButtonOptions:{format:'png',scale:2}};
function draw(id,traces,layout={}){
 const base={font:{family:'system-ui, sans-serif',size:12,color:'#304c55'},paper_bgcolor:'#ffffff',plot_bgcolor:'#ffffff',margin:{l:60,r:20,t:25,b:80},height:360,hovermode:'closest',legend:{orientation:'h',y:-.28,x:0},colorway:COLORS,xaxis:{gridcolor:'#e4eae7',zerolinecolor:'#788a8c',automargin:true},yaxis:{gridcolor:'#e4eae7',automargin:true}};
 for(const axis of ['xaxis','yaxis'])if(typeof layout[axis]?.title==='string')layout[axis].title={text:layout[axis].title};
 const promise=Plotly.react(id,traces,{...base,...layout},config);plotJobs.push(promise);return promise;
}
function bars(id,rows,limit,salary){
 rows=[...rows].sort((a,b)=>b.mean-a.mean);if(limit!=='all')rows=rows.slice(0,+limit);rows.reverse();
 const labels=rows.map(r=>{let x=r.Group.replace('Developer, ','Dev: ');return x.length>29?x.slice(0,27)+'…':x;});
 const traces=[{type:'bar',orientation:'h',y:labels,x:rows.map(r=>r.mean),name:salary?'Mean salary':'Mean satisfaction',marker:{color:COLORS[0]},customdata:rows.map(r=>[r.Group,r.n]),hovertemplate:'%{customdata[0]}<br>n=%{customdata[1]:,}<br>Mean: '+(salary?'$':'')+'%{x:,.2f}<extra></extra>'}];
 if(salary)traces.push({type:'scatter',mode:'markers',name:'Median',x:rows.map(r=>r.median),y:labels,marker:{color:COLORS[1],size:8},hovertemplate:'Median: $%{x:,.2f}<extra></extra>'});
 draw(id,traces,{height:Math.max(390,rows.length*33+110),margin:{l:175,r:20,t:15,b:75},xaxis:{title:salary?'Annual compensation (USD)':'Mean rating (0–10)',range:salary?undefined:[0,10],rangemode:'tozero',tickprefix:salary?'$':'',automargin:true},yaxis:{automargin:true,tickfont:{size:11}},showlegend:salary});
}
function hist(id,data,filter='all'){
 const rows=filter==='all'?data.series:data.series.filter(s=>s.name===filter);
 const traces=rows.map(s=>({type:'scatter',mode:'lines',line:{shape:'hv',width:2,color:COLORS[data.series.indexOf(s)]},fill:'tozeroy',opacity:.7,name:s.name,x:data.edges,y:[...s.density,0],customdata:[...s.counts,0],hovertemplate:'%{fullData.name}<br>Bin start: %{x:,.2f}<br>Density: %{y:.5f}<br>Draws in bin: %{customdata:,}<extra></extra>'}));
 draw(id,traces,{xaxis:{title:data.unit==='USD thousands'?'USD thousands':'Centered difference / SD',automargin:true},yaxis:{title:'Probability density',automargin:true},shapes:data.edges[0]<0&&data.edges.at(-1)>0?[{type:'line',x0:0,x1:0,y0:0,y1:1,yref:'paper',line:{color:'#52666a',dash:'dot'}}]:[]});
}
function ageChart(a){
 const x=a.age_edges.slice(0,-1).map((v,i)=>(v+a.age_edges[i+1])/2),y=a.log_salary_edges.slice(0,-1).map((v,i)=>(v+a.log_salary_edges[i+1])/2);
 draw('age-chart',[{type:'heatmap',x,y,z:y.map((_,j)=>x.map((_,i)=>a.counts[i][j]||null)),colorscale:[[0,'#e8f1f2'],[1,'#00728a']],colorbar:{title:{text:'Respondents'},thickness:14},hoverongaps:false,hovertemplate:'Age-bin center: %{x} years<br>log10 salary-bin center: %{y}<br>Respondents: %{z:,}<extra></extra>'}],{height:420,xaxis:{title:'Recorded age (5-year bins)',range:[0,85]},yaxis:{title:'Annual USD (logarithmic scale)',tickvals:[2,3,4,5,6,7],ticktext:['$100','$1k','$10k','$100k','$1m','$10m']},margin:{l:70,r:45,t:20,b:65}});
}
function ciChart(rows){draw('ci-chart',rows.map((r,i)=>({type:'scatter',mode:'markers',name:r.Group,x:[DATA.scalars.mean_difference],y:[r.Group],error_x:{type:'data',symmetric:false,array:[r['Upper USD']-DATA.scalars.mean_difference],arrayminus:[DATA.scalars.mean_difference-r['Lower USD']],thickness:4,width:9},marker:{color:COLORS[i],size:9},customdata:[[r['Lower USD'],r['Upper USD']]],hovertemplate:'%{y}<br>Gap: $%{x:,.2f}<br>95% CI: $%{customdata[0]:,.2f} to $%{customdata[1]:,.2f}<extra></extra>'})),{height:240,showlegend:false,margin:{l:165,r:25,t:25,b:65},xaxis:{title:'Remote − Hybrid mean salary (USD)',rangemode:'tozero',tickprefix:'$'},yaxis:{automargin:true}});}
async function init(){const embedded=$('dashboard-data');if(!embedded)throw Error('Embedded summary missing');const d=DATA=JSON.parse(embedded.textContent),m=d.meta,s=d.scalars,t=d.tests,e=d.extra,T=d.tables,B=m.replications;put('verified-date',`Verified ${m.verified_date}`);
$('metrics').innerHTML=[[usd(s.mean_difference),'Remote − Hybrid mean gap'],[usd(s.median_difference),'Remote − Hybrid median gap'],[integer(s.n_remote+s.n_hybrid),'Work-mode respondents'],[integer(s.total_n),'US/Canada degree respondents']].map(([v,k])=>`<div class="metric"><strong>${v}</strong><span>${k}</span></div>`).join('');
$('takeaways').innerHTML=`<p><b>Remote pay is higher in this sample.</b>The observed mean gap is ${num(100*s.mean_difference/s.mean_hybrid,1)}% of the hybrid mean. Both confidence intervals exclude zero.</p><p><b>The high-salary tail matters.</b>Means exceed medians; the IQR sensitivity check retains the positive work-mode gap.</p><p><b>Education is associated with salary.</b>US/Canada group means differ overall. The test does not identify significant pairs or isolate a degree’s causal effect.</p>`;
put('dataset',`${integer(m.rows)} salary-reporting respondents across ${integer(m.countries)} countries, with ${integer(m.columns)} supplied variables. Salaries are annual USD. This is the selected population from the cleaned assignment dataset, not the entire survey.`);
table('selection-table',T.selection_flow,['Stage','Excluded at stage','Remaining']);table('employment-table',T.employment_audit);put('selection-copy',`The original ${integer(m.original_n)} respondents lose ${m.retired_n} explicit retired classifications and ${m.over_80_n} recorded ages above 80, with ${m.overlap_n} overlap, leaving ${integer(m.rows)}. Age 80 remains eligible (${m.age80_n} respondents). These researcher-defined scope decisions precede every analysis and are distinct from data cleaning or salary-outlier removal. Retirement is explicitly recorded in DevType, although both excluded records also say Employed. Transitioning to retirement alone is not excluded. The ${m.missing_age} missing ages remain outside the age plot; eligibility against the ceiling cannot be verified for them. Students and respondents marked Not employed remain: this is not a verified employed-only sample.`);put('sat-diagnostic',e.diagnostics[0]);put('salary-diagnostic',e.diagnostics[1]);put('age-diagnostic',e.diagnostics[2]);
function titleCharts(){bars('sat-chart',T.satisfaction_by_title,$('sat-limit').value,false);bars('salary-chart',T.salary_by_title,$('salary-limit').value,true);}titleCharts();$('sat-limit').addEventListener('change',titleCharts);$('salary-limit').addEventListener('change',titleCharts);ageChart(d.charts.age);
put('age-privacy',`Public-safe transformation of the notebook scatterplot: 5-year age bins and 0.25-log10 salary bins. Cells below ${d.charts.age.minimum_cell_count} responses are suppressed (${integer(d.charts.age.suppressed_observations)} observations); ${integer(d.charts.age.plotted_observations)} appear in the count grid. Sparse extremes may not be visible here. Suppression affects this display only; no salaries are removed from the tests.`);
put('preparation',`Exclude ${integer(m.missing_satisfaction)} missing ratings and ${m.invalid_satisfaction} rating of 60 only from satisfaction averages, using an explicit 0–10 working validity rule. Ratings are ordinal; averages are the requested numerical summary. Omit ${m.missing_age} missing ages only from the age plot. Age is already numeric; no age-range midpoints are invented and its prior cleaning history is unknown. DevType contains one supplied category per row, so no multiple-response expansion is imposed. Retain ${m.duplicates} exact duplicate rows because respondent identity cannot be verified. The retirement and age >80 selection rules apply to every analysis; satisfaction validity and other age diagnostics cause no further Q2/Q3 exclusions.`);table('satisfaction-sensitivity',T.sat_sensitivity);
put('q2-intro',`Remote respondents have mean salary ${usd(s.mean_remote)} versus ${usd(s.mean_hybrid)} for Hybrid. The samples contain ${integer(s.n_remote)} and ${integer(s.n_hybrid)} respondents; the other ${integer(m.rows-s.n_remote-s.n_hybrid)} respondents fall outside these exact work-mode labels.`);table('q2-descriptives',T.q2_descriptives);table('q2-outliers',T.q2_outliers);table('q2-sensitivity',T.q2_sensitivity);
put('q2-test-result',`The pooled test rejects equal population means at α = ${m.alpha} (two-sided p = ${prob(s.manual_p)}). The observed difference is ${usd(s.mean_difference)}. This is an unadjusted association, not a pay increase caused by remote work.`);
table('q2-test-table',[{Method:'Manual pooled t',t:s.manual_t,df:s.degrees_freedom,'p-value':s.manual_p},{Method:'SciPy pooled t',t:t.student.statistic,df:t.student.df,'p-value':t.student.pvalue},{Method:'Welch supplement',t:t.welch.statistic,df:t.welch.df,'p-value':t.welch.pvalue}]);
table('manual-table',Object.entries(e.manual_steps).map(([k,v])=>({Step:k,Value:/p-value/.test(k)?prob(v):/statistic/.test(k)?num(v,5):/ n|freedom/.test(k)?integer(v):num(v)})));
put('q2-assumptions',`Manual and matching SciPy results agree within floating-point tolerance. The variance ratio is ${num(s.variance_ratio_q2)}; median-centered Levene’s p = ${prob(t.q2_levene.pvalue)} calls equal variances into question. Welch’s test reaches the same decision. Large groups support approximation, but severe skew and extremes can slow convergence. Independence is assumed and is not established by the available columns.`);
table('bootstrap-summary',T.q2_boot_summary);table('anova-table',T.q3_anova_results);put('q2-bootstrap-method',`Draw with replacement independently within each group, using ${integer(B)} replications and seed ${m.seed} with named independent random streams. Each resample contains ${integer(s.n_remote)} Remote and ${integer(s.n_hybrid)} Hybrid salaries—the original group sizes. The bootstrap standard error of the difference is ${usd(d.charts.q2difference.series[0].sd*1000)}.`);
for(const id of ['q2means','q2difference','q2standardized','q3means'])hist(id,d.charts[id]);
put('q2-bootstrap-test',`The assignment-required pooled t-test uses two arrays of ${integer(B)} unshifted bootstrap means: t = ${num(t.bootstrap_means_t.statistic,5)}, df = ${integer(t.bootstrap_means_t.df)}; p is below floating-point resolution, not literally zero. It rejects at 0.05, like Q2(b), but does not supply independent population evidence. Its nominal SE shrinks with 1/√B.`);
put('q2-null-test',`The separate null-centered test finds ${integer(t.q2_boot_test.exceedances)} extreme draws out of ${integer(B)}: p = ${prob(t.q2_boot_test.p)}; reject at 0.05. Its exact 95% Monte Carlo tail interval is ${prob(t.q2_boot_test['MC tail lower'])} to ${prob(t.q2_boot_test['MC tail upper'])}, describing simulation uncertainty only.`);
put('ci-intro',`Both 95% intervals exclude zero and support a positive mean gap. They quantify uncertainty in an unadjusted population comparison, not the salary benefit an individual would receive.`);table('ci-table',T.q2_cis);ciChart(T.q2_cis);
put('ci-method',`The pooled interval uses observed gap ± t critical × pooled SE: ${usd(s.mean_difference)} ± ${usd(s.margin_of_error)}, with critical t = ${num(s.critical_t,5)} and df = ${integer(s.degrees_freedom)}. The bootstrap interval takes the 2.5th and 97.5th percentiles of the unshifted differences. Its width is ${usd(T.q2_cis[1]['Width USD']-T.q2_cis[0]['Width USD'])} greater than the formula interval.`);
put('median-intro',`The Remote median is ${usd(s.median_remote)} and the Hybrid median is ${usd(s.median_hybrid)}: a typical-salary gap of ${usd(s.median_difference)}. Both median methods reject equality at 0.05, while answering the question through different statistics.`);
table('median-table',[{Method:'Mood’s median test','Statistic / draws':`χ²(1) = ${num(t.mood.statistic,5)}`,'p-value':t.mood.pvalue},{Method:'Null-centered median bootstrap','Statistic / draws':`${t.q2_median_boot_test.exceedances} / ${integer(B)} extreme draws`,'p-value':t.q2_median_boot_test.p}]);table('median-counts',T.contingency);
put('median-method',`The pooled median is ${usd(t.mood.median)}. Ties (${e.median_ties.Remote} Remote, ${e.median_ties.Hybrid} Hybrid) go in the “at/below” group; Yates correction is enabled and the smallest expected count is ${num(e.median_expected_min)}. Independently resample medians at the original group sizes, shifting each group to the pooled median. Equivalently subtract the observed median gap from each bootstrap gap. Count absolute null differences at least as large as ${usd(s.median_difference)}. The plus-one p = (hits + 1)/(B + 1) is ${prob(t.q2_median_boot_test.p)}. With zero hits this is the reporting floor, not a precise tail estimate; the exact 95% Monte Carlo upper bound is ${prob(t.q2_median_boot_test['MC tail upper'])}.`);
put('education-scope',`Restrict all Q3 analyses to exact Country labels “${e.countries.join('” or “')}” (${integer(m.q3_country_count)} respondents), then select “${e.education_labels.join('”, “')}” (${integer(s.total_n)} respondents). Professional is the supplied category; no unprovided degree composition is inferred.`);table('education-table',T.q3_descriptives);table('education-outliers',T.q3_outliers);table('education-sensitivity',T.q3_sensitivity);
put('education-sensitivity-note',`The IQR-restricted ANOVA gives F = ${num(t.trimmed_anova.statistic,5)}, p = ${prob(t.trimmed_anova.pvalue)}. The Professional-minus-Master’s mean gap narrows to $48.17 after restriction; the apparent separation is sensitive to the salary tail. This comparison targets truncated distributions.`);
put('anova-result',`Ordinary ANOVA gives F(${integer(s.df_between)}, ${integer(s.df_within)}) = ${num(t.anova.statistic,5)}, p = ${prob(t.anova.pvalue)}. Reject equal means at 0.05: at least one degree-group mean differs. It does not establish that all pairs differ or that education caused the gap.`);
put('anova-assumptions',`Unequal group sizes, skewness and a variance ratio of ${num(s.variance_ratio_q3)} challenge the ordinary ANOVA assumptions. Median-centered Levene’s p = ${prob(t.q3_levene.pvalue)}. Supplementary Welch ANOVA gives F(${integer(s.df_between)}, ${num(s.welch_df2)}) = ${num(s.welch_f,5)}, p = ${prob(s.welch_anova_p)}, also rejecting equal means.`);
put('education-bootstrap',`${integer(B)} replications use seed ${m.seed} and separate degree streams. Resample sizes are ${T.q3_descriptives.map(r=>`${r.Group}: ${integer(r.n)}`).join('; ')}. The simulated mean standard errors are ${d.charts.q3means.series.map(r=>`${r.name}: ${usd(r.sd*1000)}`).join('; ')}.`);
const select=$('pair-select');d.charts.q3differences.series.forEach(r=>{const o=document.createElement('option');o.value=r.name;o.textContent=r.name;select.append(o);});function pairs(){hist('q3differences',d.charts.q3differences,select.value);hist('q3standardized',d.charts.q3standardized,select.value);}pairs();select.addEventListener('change',pairs);
put('education-gaps',`Observed mean gaps: ${Object.entries(e.pair_differences).map(([k,v])=>`${k}: ${usd(v)}`).join('; ')}.`);
put('anova-bootstrap',`The required ANOVA receives three arrays of ${integer(B)} unshifted bootstrap means: F(2, ${integer(3*B-3)}) = ${num(t.bootstrap_means_anova.statistic,5)}; p is below floating-point resolution, not zero. It rejects at 0.05, like Q3(b). The statistic and p-value depend on the simulation count; this adds no respondents or independent evidence.`);
put('anova-null',`The separate null-centered F test finds ${t.q3_boot_test.exceedances} extreme draw out of ${integer(B)}, giving p = ${prob(t.q3_boot_test.p)}; reject at 0.05. The exact 95% Monte Carlo tail interval is ${prob(t.q3_boot_test['MC tail lower'])} to ${prob(t.q3_boot_test['MC tail upper'])}. Sparse exceedances cannot resolve tails as small as the classical ANOVA p-value.`);
$('provenance').innerHTML=`<p>Analysis verified ${esc(m.verified_date)} by executing the notebook’s calculations in memory, including its numerical assertions. ${integer(B)} bootstrap replications; seed ${m.seed}; α = ${m.alpha}. The original notebook and CSV are unchanged.</p><p>CSV SHA-256: <code>${esc(m.input_sha256)}</code><br>Notebook SHA-256: <code>${esc(m.notebook_sha256)}</code><br>Final report SHA-256: <code>${esc(m.report_sha256)}</code></p>`;
document.querySelectorAll('details').forEach(el=>el.addEventListener('toggle',()=>{if(el.open)el.querySelectorAll('.js-plotly-plot').forEach(p=>Plotly.Plots.resize(p));}));await Promise.all(plotJobs); document.documentElement.dataset.ready='true';$('load-status').hidden=true;}
init().catch(err=>{console.error(err);$('load-status').hidden=true;$('load-error').hidden=false;$('load-error').textContent='The dashboard could not finish loading its charts. Please reload this page. Error: '+err.message;});
